    .filter((v) => v !== view.root)
    .map((v) => ({
      u: view.parent.get(v)!,
      v,
      mask: view.masks.get(v === outgroup ? view.root : v)!,
      length: tree.edges.get(v)!.get(view.parent.get(v)!)!,
