  const queue = [from];
  for (let i = 0; i < queue.length; i++) {
    const v = queue[i];
    const current = result.get(v)!;
    for (const [next, length] of tree.edges.get(v)!) {
      if (!result.has(next)) {
        result.set(next, { length: current.length + length, steps: current.steps + 1 });
        queue.push(next);
