    const next = view.children.get(v)!;
    minimum.set(v, next.length ? next.map((c) => minimum.get(c)!).sort()[0] : names[v]);
    children.set(
      v,
      [...next].sort((a, b) =>
        minimum.get(a)! < minimum.get(b)! ? -1 : minimum.get(a)! > minimum.get(b)! ? 1 : 0,
      ),
    );
